// TempFile creates a temporary file which is marked as delete-on-close
func TempFile(dir, prefix string) (f *os.File, err error) {
	// slightly modified implementation of os.CreateTemp(dir, prefix) to allow us to add
	// the FILE_ATTRIBUTE_TEMPORARY | FILE_FLAG_DELETE_ON_CLOSE flags.
	// These provide two large benefits:
	// FILE_ATTRIBUTE_TEMPORARY tells Windows to keep the file in memory only if possible
	// which reduces the amount of unnecessary disk writes.
	// FILE_FLAG_DELETE_ON_CLOSE instructs Windows to automatically delete the file once
	// all file descriptors are closed.

	if dir == "" {
		dir = os.TempDir()
	}

	access := uint32(windows.GENERIC_READ | windows.GENERIC_WRITE)
	creation := uint32(windows.CREATE_NEW)
	share := uint32(0) // prevent other processes from accessing the file
	flags := uint32(windows.FILE_ATTRIBUTE_TEMPORARY | windows.FILE_FLAG_DELETE_ON_CLOSE)

	for i := 0; i < 10000; i++ {
		randSuffix := strconv.Itoa(int(1e9 + rand.Intn(1e9)%1e9))[1:]
		path := filepath.Join(dir, prefix+randSuffix)

		ptr, err := windows.UTF16PtrFromString(path)
		if err != nil {
			return nil, err
		}
		h, err := windows.CreateFile(ptr, access, share, nil, creation, flags, 0)
		if os.IsExist(err) {
			continue
		}
		// Access denied error can occur if the tmp files conflict with each other.
		if isAccessDeniedError(err) {
			continue
		}
		return os.NewFile(uintptr(h), path), err
	}

	// Proper error handling is still to do
	return nil, os.ErrExist
}

func isAccessDeniedError(err error) bool {
	if errno, ok := err.(syscall.Errno); ok {
		return errno == windows.ERROR_ACCESS_DENIED
	}
	return false
}

func (r *Repository) WithBlobUploader(ctx context.Context, fn func(ctx context.Context, uploader restic.BlobSaverWithAsync) error) error {
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()
	wg, ctx := errgroup.WithContext(ctx)
	// pack uploader + wg.Go below + blob saver (CPU bound)
	wg.SetLimit(2 + runtime.GOMAXPROCS(0))
	r.mainWg = wg
	r.startPackUploader(ctx, wg)
	// blob saver are spawned on demand, use wait group to keep track of them
	r.blobSaver = &sync.WaitGroup{}
	wg.Go(func() error {
		inCallback := true
		defer func() {
			// when the defer is called while inCallback is true, this means
			// that runtime.Goexit was called within `fn`. This should only happen
			// if a test uses t.Fatal within `fn`.
			if inCallback {
				cancel()
			}
		}()
		err := fn(ctx, &blobSaverRepo{repo: r})
		inCallback = false
		if err != nil {
			return err
		}
		if err := r.flush(ctx); err != nil {
			return fmt.Errorf("error flushing repository: %w", err)
		}
		return nil
	})
	return wg.Wait()
}

func (r *Repository) startPackUploader(ctx context.Context, wg *errgroup.Group) {
	if r.packerWg != nil {
		panic("uploader already started")
	}

	innerWg, ctx := errgroup.WithContext(ctx)
	r.packerWg = innerWg
	r.uploader = newPackerUploader(ctx, innerWg, r, r.Connections())
	r.treePM = newPackerManager(r.key, restic.TreeBlob, r.PackSize(), r.packerCount, r.uploader.QueuePacker)
	r.dataPM = newPackerManager(r.key, restic.DataBlob, r.PackSize(), r.packerCount, r.uploader.QueuePacker)

	wg.Go(func() error {
		return innerWg.Wait()
	})
}

